package holamundo;

public class OperadoresAritmeticos {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		        int a = 10;
		        int b = 3;

		        // Operador unario de cambio de signo
		        int negativo = -a;
		        System.out.println("Cambio de signo: -" + a + " = " + negativo);

		        // Suma
		        int suma = a + b;
		        System.out.println("Suma: " + a + " + " + b + " = " + suma);

		        // Resta
		        int resta = a - b;
		        System.out.println("Resta: " + a + " - " + b + " = " + resta);

		        // Producto
		        int producto = a * b;
		        System.out.println("Producto: " + a + " * " + b + " = " + producto);

		        // División
		        double division = a / b;
		        System.out.println("División: " + a + " / " + b + " = " + division);

		        // Módulo (residuo)
		        int modulo = a % b;
		        System.out.println("Módulo: " + a + " % " + b + " = " + modulo);

		
		
		
	}

}
